package desync

import "github.com/sagernet/sing-box/common/windivert"

// The checksum policy is part of preserving captured and generated bytes.
//
// A generated fake or replacement already contains the planner's deliberate
// checksums, including intentionally invalid ones; the driver must be told the
// bytes are supplied, otherwise it would recompute the strategy away. Bytes this
// process rewrote (an in-place modification) have no valid checksum for the new
// headers, so the driver must recompute them. A pass-through original keeps the
// captured address exactly as the driver reported it: the offload metadata of
// that packet stays authoritative.
//
// These are pure helpers so both directions of the policy are regression-tested
// without a Windows host.

// suppliedChecksums marks every checksum field of the send address as already
// supplied by the packet bytes.
func suppliedChecksums(address *windivert.Address) {
	address.SetIPChecksum(true)
	address.SetTCPChecksum(true)
	address.SetUDPChecksum(true)
}

// recomputeChecksums clears every checksum-valid flag so the driver materializes
// the checksums of the bytes that are actually sent.
func recomputeChecksums(address *windivert.Address) {
	address.SetIPChecksum(false)
	address.SetTCPChecksum(false)
	address.SetUDPChecksum(false)
}
